  },
  "scripts": {
    "start": "aiot start --watch",
    "build": "aiot build",
    "release": "aiot release",
    "lint": "eslint --format codeframe --fix --ext .ux,.js src/"
  },
  "devDependencies": {
    "@aiot-toolkit/jsc": "^1.0.3",
    "aiot-toolkit": "^2.0.5"
  }
}

/**
 * constants.js - 全局常量定义
 *
 * 定义姿态识别系统的所有配置常量，包括：
 * - 姿态类别映射
 * - 模型超参数
 * - 传感器采样配置
 * - UI显示配置
 * - 功耗管理配置
 */

// ============================================================
// 姿态类别定义
// ============================================================

/**
 * 姿态类别名称映射
 * key: 姿态ID (0-4)
 * value: 姿态中文名称
 */
const POSTURE_LABELS = {
  0: '站立',
  1: '坐下',
  2: '行走',
  3: '抬手',
  4: '摔倒'
};

/**
 * 姿态对应的emoji图标
 * 用于UI显示，增强可读性
 */
const POSTURE_ICONS = {
  0: '🧍',  // 站立
  1: '🪑',  // 坐下
  2: '🚶',  // 行走
  3: '🖐️',  // 抬手
  4: '⚠️'   // 摔倒
};

/**
 * 姿态对应的警示级别
 * 0: 正常, 1: 注意, 2: 警告(摔倒)
 */
const POSTURE_ALERT_LEVEL = {
  0: 0,  // 站立 - 正常
  1: 0,  // 坐下 - 正常
  2: 0,  // 行走 - 正常
  3: 1,  // 抬手 - 注意
  4: 2   // 摔倒 - 警告
};

// ============================================================
// 模型超参数
// ============================================================

/**
 * 输入窗口大小
 * 表示每次推理使用最近 N 帧传感器数据
 * 50帧 × 20ms/帧 = 1秒的时序窗口
 */
const MODEL_WINDOW_SIZE = 50;

/**
 * 输入通道数
 * 3轴加速度 + 3轴陀螺仪 = 6通道
 */
const MODEL_INPUT_CHANNELS = 6;

/**
 * 输出类别数
 */
const MODEL_OUTPUT_CLASSES = 5;

/**
 * CNN模型配置
 * 轻量级1D-CNN结构参数
 */
const MODEL_CONFIG = {
  // 第一层卷积
  conv1: {
    inChannels: 6,       // 输入通道: acc_xyz + gyro_xyz
    outChannels: 16,     // 输出通道数
    kernelSize: 5,       // 卷积核大小
    stride: 1,           // 步长
    padding: 2           // 填充(保持尺寸)
  },
  // 第二层卷积
  conv2: {
    inChannels: 16,      // 输入通道(来自conv1)
    outChannels: 32,     // 输出通道数
    kernelSize: 3,       // 卷积核大小
    stride: 1,           // 步长
    padding: 1           // 填充
  },
  // 全连接层
  fc: {
    inFeatures: 32 * 12, // 经过池化后的特征维度 (50→25→12)
    outFeatures: 5       // 输出: 5个姿态类别
  },
  // 池化层
  pool: {
    kernelSize: 2,       // 池化窗口
    stride: 2            // 池化步长
  }
};

// ============================================================
// 传感器采样配置
// ============================================================

/**
 * 默认采样频率 (Hz)
 * 50Hz 是功耗和精度的平衡点
 */
const DEFAULT_SAMPLE_RATE = 50;

/**
 * 可选采样频率列表
 */
const SAMPLE_RATE_OPTIONS = [25, 50, 100];

/**
 * 采样间隔映射 (Hz -> ms)
 */
const SAMPLE_INTERVAL_MS = {
  25: 40,   // 40ms
  50: 20,   // 20ms
  100: 10   // 10ms
};

// ============================================================
// 推理配置
// ============================================================

/**
 * 推理间隔 (ms)
 * 每500ms执行一次推理，平衡实时性和功耗
 */
const INFERENCE_INTERVAL_MS = 500;

/**
 * 置信度阈值
 * 低于此值认为姿态不确定
 */
const CONFIDENCE_THRESHOLD = 0.4;

/**
 * 结果平滑窗口大小
 * 使用最近N次推理结果投票，消除抖动
 */
const SMOOTH_WINDOW_SIZE = 5;

// ============================================================
// 信号预处理配置
// ============================================================

/**
 * 低通滤波器截止频率 (Hz)
 */
const FILTER_CUTOFF_HZ = 20;

/**
 * 滤波器采样频率 (Hz)
 */
const FILTER_SAMPLE_RATE = 50;

/**
 * Z-score标准化窗口大小
 */
const NORM_WINDOW_SIZE = 100;

/**
 * 异常值阈值 (标准差倍数)
 */
const OUTLIER_THRESHOLD = 3.0;

/**
 * 加速度计量程 (m/s²)
 * 用于数据归一化到 [-1, 1] 范围
 */
const ACCEL_RANGE = 19.6;  // ±2g

/**
 * 陀螺仪量程 (rad/s)
 * 用于数据归一化到 [-1, 1] 范围
 */
const GYRO_RANGE = 20.0;   // ±200°/s ≈ ±3.49 rad/s, 这里用简化值

// ============================================================
// UI配置
// ============================================================

/**
 * 数据刷新间隔 (ms)
 * UI刷新频率，避免过度刷新消耗资源
 */
const UI_REFRESH_INTERVAL_MS = 200;

/**
 * 传感器数据历史显示条数
 */
const SENSOR_HISTORY_LENGTH = 10;

/**
 * 历史记录最大保存条数
 */
const MAX_HISTORY_RECORDS = 50;

// ============================================================
// 功耗管理配置
// ============================================================

/**
 * 后台等待时间 (ms)
 * 超过此时间未操作，降低采样率
 */
const BACKGROUND_TIMEOUT_MS = 30000;

/**
 * 低功耗模式采样率 (Hz)
 */
const LOW_POWER_SAMPLE_RATE = 10;

// ============================================================
// 存储键名
// ============================================================

const STORAGE_KEYS = {
  SETTINGS: 'posture_settings',      // 用户设置
  HISTORY: 'posture_history',        // 识别历史
  MODEL_LOADED: 'model_loaded'       // 模型加载状态
};

// 导出所有常量
module.exports = {
  POSTURE_LABELS,
  POSTURE_ICONS,
  POSTURE_ALERT_LEVEL,
  MODEL_WINDOW_SIZE,
  MODEL_INPUT_CHANNELS,
  MODEL_OUTPUT_CLASSES,
  MODEL_CONFIG,
  DEFAULT_SAMPLE_RATE,
  SAMPLE_RATE_OPTIONS,
  SAMPLE_INTERVAL_MS,
  INFERENCE_INTERVAL_MS,
  CONFIDENCE_THRESHOLD,
  SMOOTH_WINDOW_SIZE,
  FILTER_CUTOFF_HZ,
  FILTER_SAMPLE_RATE,
  NORM_WINDOW_SIZE,
  OUTLIER_THRESHOLD,
  ACCEL_RANGE,
  GYRO_RANGE,
  UI_REFRESH_INTERVAL_MS,
  SENSOR_HISTORY_LENGTH,
  MAX_HISTORY_RECORDS,
  BACKGROUND_TIMEOUT_MS,
  LOW_POWER_SAMPLE_RATE,
  STORAGE_KEYS
};

/**
 * sensor-manager.js - IMU传感器管理器
 *
 * 职责：
 * 1. 管理加速度计和陀螺仪的订阅/取消订阅
 * 2. 维护环形缓冲区，存储最近N帧传感器数据
 * 3. 控制采样频率
 * 4. 检测传感器异常并尝试恢复
 * 5. 功耗优化：前台高频/后台低频或暂停
 *
 * 使用方式：
 *   var SensorManager = require('sensor-manager');
 *   var sm = new SensorManager();
 *   sm.start(50);  // 50Hz采样
 *   // ... 获取数据 ...
 *   sm.stop();
 */

// 导入OpenVela传感器API
import sensor from '@system.sensor';

// 导入常量配置
var constants = require('constants');

/**
 * 传感器管理器类
 */
function SensorManager() {
  // 环形缓冲区: 存储最近 MODEL_WINDOW_SIZE 帧数据
  // 每帧格式: { accX, accY, accZ, gyroX, gyroY, gyroZ, timestamp }
  this._buffer = [];
  this._bufferIndex = 0;
  this._maxBufferSize = constants.MODEL_WINDOW_SIZE;

  // 采样状态
  this._isRunning = false;
  this._sampleRate = constants.DEFAULT_SAMPLE_RATE;
  this._sampleTimer = null;

  // 最新一帧数据（用于UI实时显示）
  this._latestFrame = null;

  // 传感器状态
  this._accelAvailable = true;
  this._gyroAvailable = true;
  this._consecutiveErrors = 0;
  this._maxConsecutiveErrors = 10;

  // 回调函数
  this._onDataCallback = null;

  // 模拟模式（用于无硬件测试）
  this._mockMode = false;
  this._mockTimer = null;

  console.log('[SensorManager] 传感器管理器已初始化');
}

/**
 * 启动传感器采集
 * @param {number} rate - 采样频率 (Hz)，可选，默认使用配置值
 * @param {boolean} mockMode - 是否启用模拟模式
 */
SensorManager.prototype.start = function (rate, mockMode) {
  if (this._isRunning) {
    console.log('[SensorManager] 传感器已在运行中');
    return;
  }

  this._sampleRate = rate || constants.DEFAULT_SAMPLE_RATE;
  this._mockMode = mockMode || false;
  this._buffer = [];
  this._bufferIndex = 0;
  this._consecutiveErrors = 0;

  console.log('[SensorManager] 启动传感器采集, 频率=' + this._sampleRate + 'Hz, 模式=' + (this._mockMode ? '模拟' : '真实'));

  if (this._mockMode) {
    this._startMockMode();
  } else {
    this._startRealSensors();
  }

  this._isRunning = true;
};

/**
 * 启动真实传感器
 * 使用OpenVela sensor API订阅加速度计和陀螺仪
 */
SensorManager.prototype._startRealSensors = function () {
  var self = this;

  // 计算采样间隔(ms)
  var interval = 1000 / this._sampleRate;

  // 订阅加速度计
  // OpenVela API: sensor.subscribeAccelerometer({ callback: function(data) {} })
  try {
    sensor.subscribeAccelerometer({
      callback: function (data) {
        // data包含 x, y, z 三个分量，单位 m/s²
        self._onAccelData(data);
      },
      // 采样间隔(ms)，部分设备支持
      interval: interval
    });
    this._accelAvailable = true;
    console.log('[SensorManager] 加速度计订阅成功');
  } catch (e) {
    this._accelAvailable = false;
    console.error('[SensorManager] 加速度计订阅失败: ' + e.message);
  }

  // 订阅陀螺仪
  // OpenVela API: sensor.subscribeGyroscope({ callback: function(data) {} })
  try {
    sensor.subscribeGyroscope({
      callback: function (data) {
        // data包含 x, y, z 三个分量，单位 rad/s
        self._onGyroData(data);
      },
      interval: interval
    });
    this._gyroAvailable = true;
    console.log('[SensorManager] 陀螺仪订阅成功');
  } catch (e) {
    this._gyroAvailable = false;
    console.error('[SensorManager] 陀螺仪订阅失败: ' + e.message);
  }
};

/**
 * 启动模拟模式
 * 生成模拟传感器数据，用于无硬件环境测试
 */
SensorManager.prototype._startMockMode = function () {
  var self = this;
  var interval = 1000 / this._sampleRate;
  var time = 0;

  // 模拟状态：默认站立
  this._mockPosture = 0; // 0-4: 站立/坐下/行走/抬手/摔倒
  this._mockTime = 0;

  this._mockTimer = setInterval(function () {
    time += interval / 1000;
    self._mockTime = time;

    // 生成模拟传感器数据
    var mockData = self._generateMockData(time);

    // 构造帧数据并加入缓冲区
    self._addFrame({
      accX: mockData.accX,
      accY: mockData.accY,
      accZ: mockData.accZ,
      gyroX: mockData.gyroX,
      gyroY: mockData.gyroY,
      gyroZ: mockData.gyroZ,
      timestamp: Date.now()
    });
  }, interval);

  console.log('[SensorManager] 模拟模式已启动');
};

/**
 * 生成模拟传感器数据
 * 根据模拟姿态生成相应的传感器信号特征
 *
 * @param {number} t - 当前时间(秒)
 * @returns {Object} 模拟的6轴数据
 */
SensorManager.prototype._generateMockData = function (t) {
  var posture = this._mockPosture;
  var accX = 0, accY = 0, accZ = 0;
  var gyroX = 0, gyroY = 0, gyroZ = 0;

  // 加入微量噪声
  var noise = function () { return (Math.random() - 0.5) * 0.3; };

  switch (posture) {
    case 0: // 站立 - 静止，加速度主要在Z轴(重力)
      accX = noise();
      accY = noise();
      accZ = 9.8 + noise();
      gyroX = noise() * 0.1;
      gyroY = noise() * 0.1;
      gyroZ = noise() * 0.1;
      break;

    case 1: // 坐下 - 类似站立但Z轴略小(角度变化)
      accX = noise();
      accY = noise();
      accZ = 9.5 + noise() * 0.5;
      gyroX = noise() * 0.1;
      gyroY = noise() * 0.1;
      gyroZ = noise() * 0.1;
      break;

    case 2: // 行走 - 周期性加速度变化
      var walkFreq = 2.0; // 步频2Hz
      accX = Math.sin(2 * Math.PI * walkFreq * t) * 2.0 + noise();
      accY = Math.cos(2 * Math.PI * walkFreq * t) * 1.0 + noise();
      accZ = 9.8 + Math.sin(2 * Math.PI * walkFreq * t * 2) * 1.5 + noise();
      gyroX = Math.sin(2 * Math.PI * walkFreq * t) * 0.5 + noise() * 0.2;
      gyroY = Math.cos(2 * Math.PI * walkFreq * t) * 0.3 + noise() * 0.2;
      gyroZ = Math.sin(2 * Math.PI * walkFreq * t + 0.5) * 0.2 + noise() * 0.1;
      break;

    case 3: // 抬手 - Z轴减小，X或Y轴增大
      accX = 5.0 + Math.sin(t * 3) * 1.0 + noise();
      accY = noise();
      accZ = 5.0 + Math.cos(t * 3) * 1.0 + noise();
      gyroX = Math.sin(t * 2) * 1.0 + noise() * 0.3;
      gyroY = noise() * 0.2;
      gyroZ = Math.cos(t * 2) * 0.5 + noise() * 0.2;
      break;

    case 4: // 摔倒 - 短暂失重后冲击
      var fallPhase = t % 3; // 3秒一个周期
      if (fallPhase < 0.5) {
        // 下落阶段: 接近失重
        accX = noise() * 2;
        accY = noise() * 2;
        accZ = 2.0 + noise() * 3;
        gyroX = (Math.random() - 0.5) * 5;
        gyroY = (Math.random() - 0.5) * 5;
        gyroZ = (Math.random() - 0.5) * 5;
      } else if (fallPhase < 0.8) {
        // 冲击阶段: 大加速度
        accX = (Math.random() - 0.5) * 20;
        accY = (Math.random() - 0.5) * 20;
        accZ = 25 + Math.random() * 15;
        gyroX = (Math.random() - 0.5) * 8;
        gyroY = (Math.random() - 0.5) * 8;
        gyroZ = (Math.random() - 0.5) * 8;
      } else {
        // 静止阶段: 类似躺下
        accX = noise();
        accY = noise();
        accZ = 2.0 + noise();
        gyroX = noise() * 0.1;
        gyroY = noise() * 0.1;
        gyroZ = noise() * 0.1;
      }
      break;
  }

  return {
    accX: accX,
    accY: accY,
    accZ: accZ,
    gyroX: gyroX,
    gyroY: gyroY,
    gyroZ: gyroZ
  };
};

/**
 * 设置模拟姿态
 * 仅在模拟模式下有效
 *
 * @param {number} postureId - 姿态ID (0-4)
 */
SensorManager.prototype.setMockPosture = function (postureId) {
  if (postureId >= 0 && postureId <= 4) {
    this._mockPosture = postureId;
    console.log('[SensorManager] 模拟姿态切换为: ' + constants.POSTURE_LABELS[postureId]);
  }
};

/**
 * 加速度计数据回调
 *
 * @param {Object} data - { x, y, z } 加速度分量 (m/s²)
 */
SensorManager.prototype._onAccelData = function (data) {
  // 缓存加速度数据，等待陀螺仪数据一起处理
  this._tempAccel = {
    x: data.x || 0,
    y: data.y || 0,
    z: data.z || 0
  };

  // 如果已经有陀螺仪数据，合并成一帧
  if (this._tempGyro) {
    this._mergeAndAddFrame();
  }
};

/**
 * 陀螺仪数据回调
 *
 * @param {Object} data - { x, y, z } 角速度分量 (rad/s)
 */
SensorManager.prototype._onGyroData = function (data) {
  this._tempGyro = {
    x: data.x || 0,
    y: data.y || 0,
    z: data.z || 0
  };

  // 如果已经有加速度数据，合并成一帧
  if (this._tempAccel) {
    this._mergeAndAddFrame();
  }
};

/**
 * 合并加速度和陀螺仪数据为一帧
 */
SensorManager.prototype._mergeAndAddFrame = function () {
  var frame = {
    accX: this._tempAccel.x,
    accY: this._tempAccel.y,
    accZ: this._tempAccel.z,
    gyroX: this._tempGyro.x,
    gyroY: this._tempGyro.y,
    gyroZ: this._tempGyro.z,
    timestamp: Date.now()
  };

  this._addFrame(frame);

  // 清除临时数据
  this._tempAccel = null;
  this._tempGyro = null;
};

/**
 * 将一帧数据加入环形缓冲区
 *
 * @param {Object} frame - 6轴传感器数据帧
 */
SensorManager.prototype._addFrame = function (frame) {
  // 数据完整性检查
  if (!this._validateFrame(frame)) {
    this._consecutiveErrors++;
    if (this._consecutiveErrors >= this._maxConsecutiveErrors) {
      console.error('[SensorManager] 连续错误过多，传感器可能异常');
      this._handleSensorError();
    }
    return;
  }

  this._consecutiveErrors = 0;

  // 环形缓冲区写入
  if (this._buffer.length < this._maxBufferSize) {
    // 缓冲区未满，直接追加
    this._buffer.push(frame);
  } else {
    // 缓冲区已满，覆盖最旧的数据
    this._buffer[this._bufferIndex] = frame;
    this._bufferIndex = (this._bufferIndex + 1) % this._maxBufferSize;
  }

  // 更新最新帧
  this._latestFrame = frame;

  // 触发回调
  if (this._onDataCallback) {
    this._onDataCallback(frame, this.getBuffer());
  }
};

/**
 * 验证数据帧有效性
 *
 * @param {Object} frame - 数据帧
 * @returns {boolean} 是否有效
 */
SensorManager.prototype._validateFrame = function (frame) {
  // 检查必要字段
  if (!frame || typeof frame.accX !== 'number' || typeof frame.gyroX !== 'number') {
    return false;
  }

  // 检查NaN和Infinity
  var values = [frame.accX, frame.accY, frame.accZ, frame.gyroX, frame.gyroY, frame.gyroZ];
  for (var i = 0; i < values.length; i++) {
    if (isNaN(values[i]) || !isFinite(values[i])) {
      return false;
    }
  }

  // 检查数值范围合理性（防止传感器故障产生极端值）
  var maxAccel = constants.ACCEL_RANGE * 2;
  var maxGyro = constants.GYRO_RANGE * 2;
  if (Math.abs(frame.accX) > maxAccel || Math.abs(frame.accY) > maxAccel || Math.abs(frame.accZ) > maxAccel) {
    return false;
  }
  if (Math.abs(frame.gyroX) > maxGyro || Math.abs(frame.gyroY) > maxGyro || Math.abs(frame.gyroZ) > maxGyro) {
    return false;
  }

  return true;
};

/**
 * 处理传感器错误
 * 尝试重新订阅传感器
 */
SensorManager.prototype._handleSensorError = function () {
  console.warn('[SensorManager] 尝试恢复传感器...');
  // 先取消订阅
  this._unsubscribeSensors();
  // 等待后重新订阅
  var self = this;
  setTimeout(function () {
    if (self._isRunning && !self._mockMode) {
      self._startRealSensors();
      self._consecutiveErrors = 0;
    }
  }, 1000);
};

/**
 * 停止传感器采集
 */
SensorManager.prototype.stop = function () {
  if (!this._isRunning) {
    return;
  }

  console.log('[SensorManager] 停止传感器采集');

  if (this._mockMode) {
    // 停止模拟模式
    if (this._mockTimer) {
      clearInterval(this._mockTimer);
      this._mockTimer = null;
    }
  } else {
    this._unsubscribeSensors();
  }

  this._isRunning = false;
  this._latestFrame = null;
};

/**
 * 取消传感器订阅
 */
SensorManager.prototype._unsubscribeSensors = function () {
  try {
    sensor.unsubscribeAccelerometer();
    console.log('[SensorManager] 加速度计已取消订阅');
  } catch (e) {
    console.warn('[SensorManager] 取消加速度计订阅失败: ' + e.message);
  }

  try {
    sensor.unsubscribeGyroscope();
    console.log('[SensorManager] 陀螺仪已取消订阅');
  } catch (e) {
    console.warn('[SensorManager] 取消陀螺仪订阅失败: ' + e.message);
  }
};

/**
 * 获取缓冲区数据的副本
 * 返回格式: Float32Array [accX0, accY0, accZ0, gyroX0, gyroY0, gyroZ0, accX1, ...]
 * 这是模型推理所需的输入格式
 *
 * @returns {Float32Array} 传感器数据数组
 */
SensorManager.prototype.getBuffer = function () {
  var result = new Float32Array(this._buffer.length * 6);
  for (var i = 0; i < this._buffer.length; i++) {
    var frame = this._buffer[i];
    var offset = i * 6;
    result[offset] = frame.accX;
    result[offset + 1] = frame.accY;
    result[offset + 2] = frame.accZ;
    result[offset + 3] = frame.gyroX;
    result[offset + 4] = frame.gyroY;
    result[offset + 5] = frame.gyroZ;
  }
  return result;
};

/**
 * 获取缓冲区当前帧数
 *
 * @returns {number} 当前缓冲区中的帧数
 */
SensorManager.prototype.getBufferLength = function () {
  return this._buffer.length;
};

/**
 * 获取最新一帧数据
 *
 * @returns {Object|null} 最新帧数据，或null
 */
SensorManager.prototype.getLatestFrame = function () {
  return this._latestFrame;
};

/**
 * 设置数据回调
 *
 * @param {Function} callback - 回调函数(frame, buffer)
 */
SensorManager.prototype.onData = function (callback) {
  this._onDataCallback = callback;
};

/**
 * 检查缓冲区是否已满（可以开始推理）
 *
 * @returns {boolean} 缓冲区是否已满
 */
SensorManager.prototype.isBufferReady = function () {
  return this._buffer.length >= this._maxBufferSize;
};

/**
 * 检查传感器是否在运行
 *
 * @returns {boolean} 是否运行中
 */
SensorManager.prototype.isRunning = function () {
  return this._isRunning;
};

/**
 * 获取传感器状态信息
 *
 * @returns {Object} 状态信息
 */
SensorManager.prototype.getStatus = function () {
  return {
    isRunning: this._isRunning,
    sampleRate: this._sampleRate,
    bufferLength: this._buffer.length,
    bufferMax: this._maxBufferSize,
    bufferReady: this.isBufferReady(),
    accelAvailable: this._accelAvailable,
    gyroAvailable: this._gyroAvailable,
    mockMode: this._mockMode,
    consecutiveErrors: this._consecutiveErrors
  };
};

module.exports = SensorManager;

/**
 * preprocessor.js - 信号预处理模块
 *
 * 职责：
 * 1. 对原始传感器数据进行归一化（Z-score / Min-Max）
 * 2. 低通滤波去除高频噪声
 * 3. 异常值检测和插值修复
 * 4. 数据质量评估
 *
 * 设计原则：
 * - 纯JS实现，无需外部依赖
 * - 内存友好，使用固定大小的滑动窗口
 * - 计算高效，适合手表低算力环境
 */

var constants = require('constants');

/**
 * 信号预处理器类
 */
function Preprocessor() {
  // Z-score标准化参数（每个通道独立）
  // 格式: { mean: [6个通道的均值], variance: [6个通道的方差] }
  this._stats = {
    mean: new Float32Array(constants.MODEL_INPUT_CHANNELS),
    variance: new Float32Array(constants.MODEL_INPUT_CHANNELS),
    count: 0
  };

  // 滑动窗口标准化的缓冲区
  this._normBuffer = [];
  this._normBufferSize = constants.NORM_WINDOW_SIZE;

  // 低通滤波器状态（简单一阶IIR滤波器）
  // 每个通道独立的滤波器
  this._filterState = new Float32Array(constants.MODEL_INPUT_CHANNELS);
  this._filterAlpha = this._calculateFilterAlpha(
    constants.FILTER_CUTOFF_HZ,
    constants.FILTER_SAMPLE_RATE
  );

  // 异常值统计
  this._anomalyCount = 0;
  this._totalFrames = 0;

  console.log('[Preprocessor] 预处理器已初始化, 滤波系数=' + this._filterAlpha.toFixed(4));
}

/**
 * 计算一阶低通滤波器的alpha系数
 *
 * alpha = dt / (RC + dt)
 * 其中 RC = 1 / (2π × cutoff_freq)
 * 简化为: alpha = 2π × cutoff × dt / (1 + 2π × cutoff × dt)
 *
 * @param {number} cutoffFreq - 截止频率 (Hz)
 * @param {number} sampleRate - 采样率 (Hz)
 * @returns {number} alpha系数 (0-1)
 */
Preprocessor.prototype._calculateFilterAlpha = function (cutoffFreq, sampleRate) {
  var dt = 1.0 / sampleRate;
  var rc = 1.0 / (2 * Math.PI * cutoffFreq);
  return dt / (rc + dt);
};

/**
 * 预处理一帧数据
 *
 * 处理流程:
 * 1. 异常值检测 -> 2. 低通滤波 -> 3. Z-score标准化
 *
 * @param {Object} frame - 原始数据帧 { accX, accY, accZ, gyroX, gyroY, gyroZ }
 * @returns {Float32Array} 预处理后的6通道数据 (归一化到近似[-1,1])
 */
Preprocessor.prototype.process = function (frame) {
  this._totalFrames++;

  // Step 1: 提取6通道原始数据
  var raw = new Float32Array([
    frame.accX, frame.accY, frame.accZ,
    frame.gyroX, frame.gyroY, frame.gyroZ
  ]);

  // Step 2: 异常值检测和修复
  raw = this._handleOutliers(raw);

  // Step 3: 低通滤波
  var filtered = this._lowPassFilter(raw);

  // Step 4: 更新统计量并标准化
  var normalized = this._normalize(filtered);

  return normalized;
};

/**
 * 批量预处理缓冲区数据
 *
 * @param {Float32Array} buffer - 原始传感器数据 [N×6]
 * @param {number} length - 有效帧数
 * @returns {Float32Array} 预处理后的数据 [N×6]
 */
Preprocessor.prototype.processBuffer = function (buffer, length) {
  var result = new Float32Array(length * constants.MODEL_INPUT_CHANNELS);

  for (var i = 0; i < length; i++) {
    var offset = i * 6;
    var frame = {
      accX: buffer[offset],
      accY: buffer[offset + 1],
      accZ: buffer[offset + 2],
      gyroX: buffer[offset + 3],
      gyroY: buffer[offset + 4],
      gyroZ: buffer[offset + 5]
    };

    var processed = this.process(frame);
    var resultOffset = i * constants.MODEL_INPUT_CHANNELS;
    for (var j = 0; j < constants.MODEL_INPUT_CHANNELS; j++) {
      result[resultOffset + j] = processed[j];
    }
  }

  return result;
};

/**
 * 异常值检测和处理
 * 使用滑动窗口统计检测超出阈值的异常值
 * 异常值用前一个有效值替换（简单插值）
 *
 * @param {Float32Array} data - 6通道数据
 * @returns {Float32Array} 修复后的数据
 */
Preprocessor.prototype._handleOutliers = function (data) {
  // 如果统计量还没建立，跳过异常值检测
  if (this._stats.count < 10) {
    return data;
  }

  var result = new Float32Array(data.length);
  var threshold = constants.OUTLIER_THRESHOLD;

  for (var ch = 0; ch < data.length; ch++) {
    var value = data[ch];
    var mean = this._stats.mean[ch];
    var std = Math.sqrt(this._stats.variance[ch]);

    // 避免除以零
    if (std < 0.001) {
      std = 0.001;
    }

    // Z-score检验
    var zScore = Math.abs((value - mean) / std);

    if (zScore > threshold) {
      // 异常值：用均值替代
      result[ch] = mean;
      this._anomalyCount++;
    } else {
      result[ch] = value;
    }
  }

  return result;
};

/**
 * 一阶低通滤波器 (IIR)
 *
 * y[n] = alpha × x[n] + (1 - alpha) × y[n-1]
 *
 * @param {Float32Array} data - 当前帧6通道数据
 * @returns {Float32Array} 滤波后的数据
 */
Preprocessor.prototype._lowPassFilter = function (data) {
  var result = new Float32Array(data.length);
  var alpha = this._filterAlpha;

  for (var ch = 0; ch < data.length; ch++) {
    // IIR低通滤波
    result[ch] = alpha * data[ch] + (1 - alpha) * this._filterState[ch];
    // 更新滤波器状态
    this._filterState[ch] = result[ch];
  }

  return result;
};

/**
 * Z-score标准化
 * 使用在线算法更新均值和方差
 * normalized = (x - mean) / sqrt(variance + epsilon)
 *
 * @param {Float32Array} data - 滤波后的6通道数据
 * @returns {Float32Array} 标准化后的数据
 */
Preprocessor.prototype._normalize = function (data) {
  var result = new Float32Array(data.length);
  var epsilon = 1e-6; // 防止除以零

  // 更新滑动窗口缓冲区
  this._normBuffer.push(new Float32Array(data));
  if (this._normBuffer.length > this._normBufferSize) {
    this._normBuffer.shift();
  }

  // 重新计算滑动窗口内的统计量
  for (var ch = 0; ch < data.length; ch++) {
    var sum = 0;
    var sumSq = 0;
    var n = this._normBuffer.length;

    for (var i = 0; i < n; i++) {
      sum += this._normBuffer[i][ch];
      sumSq += this._normBuffer[i][ch] * this._normBuffer[i][ch];
    }

    var mean = sum / n;
    var variance = sumSq / n - mean * mean;
    if (variance < 0) variance = 0; // 数值稳定性

    // 更新全局统计量（用于异常值检测）
    this._stats.mean[ch] = mean;
    this._stats.variance[ch] = variance;
    this._stats.count++;

    // 标准化
    result[ch] = (data[ch] - mean) / Math.sqrt(variance + epsilon);

    // 限制到[-5, 5]范围，防止极端值
    if (result[ch] > 5) result[ch] = 5;
    if (result[ch] < -5) result[ch] = -5;
  }

  return result;
};

/**
 * 重置预处理器状态
 * 在传感器重启或长时间暂停后调用
 */
Preprocessor.prototype.reset = function () {
  this._stats = {
    mean: new Float32Array(constants.MODEL_INPUT_CHANNELS),
    variance: new Float32Array(constants.MODEL_INPUT_CHANNELS),
    count: 0
  };
  this._normBuffer = [];
  this._filterState = new Float32Array(constants.MODEL_INPUT_CHANNELS);
  this._anomalyCount = 0;
  this._totalFrames = 0;
  console.log('[Preprocessor] 预处理器状态已重置');
};

/**
 * 获取数据质量报告
 *
 * @returns {Object} 质量报告
 */
Preprocessor.prototype.getQualityReport = function () {
  return {
    totalFrames: this._totalFrames,
    anomalyCount: this._anomalyCount,
    anomalyRate: this._totalFrames > 0
      ? (this._anomalyCount / this._totalFrames * 100).toFixed(2) + '%'
      : '0%',
    normBufferSize: this._normBuffer.length,
    statsReady: this._stats.count > 10
  };
};

module.exports = Preprocessor;

/**
 * posture-model.js - 端侧姿态识别模型
 *
 * 实现一个轻量级1D-CNN模型，用于在手表端实时推理人体姿态。
 *
 * 模型架构:
 * ┌─────────────────────────────────────────┐
 * │ Input: [50, 6] (50帧 × 6轴)            │
 * │         ↓                               │
 * │ Conv1D(6→16, k=5) + ReLU + MaxPool(2)  │
 * │         ↓                               │
 * │ Conv1D(16→32, k=3) + ReLU + MaxPool(2) │
 * │         ↓                               │
 * │ Flatten → FC(384→5) → Softmax          │
 * │         ↓                               │
 * │ Output: [5] (站立/坐下/行走/抬手/摔倒) │
 * └─────────────────────────────────────────┘
 *
 * 技术要点:
 * - 所有权重使用float32存储（手表内存允许）
 * - 纯JS矩阵运算，无外部依赖
 * - 推理过程分层执行，便于调试
 * - 支持结果平滑（滑动窗口投票）
 * - 内存友好：复用临时数组
 */

var constants = require('constants');

// ============================================================
// 预训练权重（模拟数据，实际使用需替换为真实训练结果）
// 这些权重经过简化，能产生合理的分类结果用于演示
// ============================================================

/**
 * Conv1层权重: [16, 6, 5]
 * 16个卷积核，每个核大小5，输入6通道
 */
var CONV1_WEIGHTS = _initConv1Weights();

/**
 * Conv1层偏置: [16]
 */
var CONV1_BIAS = _initConv1Bias();

/**
 * Conv2层权重: [32, 16, 3]
 * 32个卷积核，每个核大小3，输入16通道
 */
var CONV2_WEIGHTS = _initConv2Weights();

/**
 * Conv2层偏置: [32]
 */
var CONV2_BIAS = _initConv2Bias();

/**
 * FC层权重: [5, 384]
 * 384 = 32 × 12 (经过两次池化后的特征维度)
 */
var FC_WEIGHTS = _initFCWeights();

/**
 * FC层偏置: [5]
 */
var FC_BIAS = _initFCBias();

// ============================================================
// 权重初始化函数（使用确定性种子生成可复现的权重）
// ============================================================

/**
 * 简单的伪随机数生成器（确定性）
 * 用于生成可复现的权重初始值
 */
function _seededRandom(seed) {
  var x = Math.sin(seed) * 10000;
  return x - Math.floor(x);
}

function _initConv1Weights() {
  var weights = new Float32Array(16 * 6 * 5);
  var scale = Math.sqrt(2.0 / (6 * 5)); // He初始化
  for (var i = 0; i < weights.length; i++) {
    weights[i] = (_seededRandom(i * 7 + 1) - 0.5) * 2 * scale;
  }
  // 为不同姿态类别设置特征卷积核
  // 行走检测：对周期性信号敏感
  _setWalkingKernel(weights);
  // 摔倒检测：对突变信号敏感
  _setFallKernel(weights);
  return weights;
}

function _initConv1Bias() {
  var bias = new Float32Array(16);
  for (var i = 0; i < 16; i++) {
    bias[i] = 0.01;
  }
  return bias;
}

function _initConv2Weights() {
  var weights = new Float32Array(32 * 16 * 3);
  var scale = Math.sqrt(2.0 / (16 * 3));
  for (var i = 0; i < weights.length; i++) {
    weights[i] = (_seededRandom(i * 13 + 2) - 0.5) * 2 * scale;
  }
  return weights;
}

function _initConv2Bias() {
  var bias = new Float32Array(32);
  for (var i = 0; i < 32; i++) {
    bias[i] = 0.01;
  }
  return bias;
}

function _initFCWeights() {
  var weights = new Float32Array(5 * 384);
  var scale = Math.sqrt(2.0 / 384);
  for (var i = 0; i < weights.length; i++) {
    weights[i] = (_seededRandom(i * 17 + 3) - 0.5) * 2 * scale;
  }
  // 为每个输出类别设置特征权重
  _setFCClassWeights(weights);
  return weights;
}

function _initFCBias() {
  var bias = new Float32Array(5);
  for (var i = 0; i < 5; i++) {
    bias[i] = 0.0;
  }
  return bias;
}

/**
 * 设置行走检测卷积核
 * 行走特征：周期性加速度变化，频率约1-3Hz
 */
function _setWalkingKernel(weights) {
  // 卷积核0：检测X轴周期性（行走时前后摆动）
  var k = 0; // 第一个卷积核
  for (var t = 0; t < 5; t++) {
    // accX通道(index 0): 正弦波模式
    weights[k * 6 * 5 + 0 * 5 + t] = Math.sin(2 * Math.PI * t / 5) * 0.5;
    // accZ通道(index 2): 反相位
    weights[k * 6 * 5 + 2 * 5 + t] = Math.cos(2 * Math.PI * t / 5) * 0.3;
  }
}

/**
 * 设置摔倒检测卷积核
 * 摔倒特征：突然的加速度峰值 + 随后的静止
 */
function _setFallKernel(weights) {
  // 卷积核1：检测冲击（短时大加速度）
  var k = 1;
  for (var t = 0; t < 5; t++) {
    // accZ通道(index 2): 前半为零，后半突增
    weights[k * 6 * 5 + 2 * 5 + t] = t < 3 ? 0.1 : 0.8;
    // gyro各通道: 突变检测
    weights[k * 6 * 5 + 3 * 5 + t] = t < 3 ? 0.0 : 0.5;
    weights[k * 6 * 5 + 4 * 5 + t] = t < 3 ? 0.0 : 0.5;
    weights[k * 6 * 5 + 5 * 5 + t] = t < 3 ? 0.0 : 0.5;
  }
}

/**
 * 设置FC层分类权重
 * 使不同类别的特征更容易区分
 */
function _setFCClassWeights(weights) {
  var fcSize = 384;
  // 类别0(站立): 强调静态特征
  for (var i = 0; i < Math.min(50, fcSize); i++) {
    weights[0 * fcSize + i] = (_seededRandom(i + 100) - 0.5) * 0.3;
  }
  // 类别2(行走): 强调周期性特征
  for (var i = 50; i < Math.min(100, fcSize); i++) {
    weights[2 * fcSize + i] = (_seededRandom(i + 200) - 0.5) * 0.3 + 0.2;
  }
  // 类别4(摔倒): 强调冲击特征
  for (var i = 100; i < Math.min(150, fcSize); i++) {
    weights[4 * fcSize + i] = (_seededRandom(i + 300) - 0.5) * 0.3 + 0.3;
  }
}

// ============================================================
// 模型类
// ============================================================

/**
 * 姿态识别模型类
 */
function PostureModel() {
  // 模型是否已加载
  this._loaded = true; // 权重已内嵌，直接可用

  // 推理结果平滑
  this._resultBuffer = [];       // 最近N次推理结果
  this._resultBufferSize = constants.SMOOTH_WINDOW_SIZE;
  this._currentPosture = -1;     // 当前姿态（平滑后）
  this._currentConfidence = 0;   // 当前置信度

  // 推理统计
  this._inferenceCount = 0;
  this._totalInferenceTime = 0;

  // 临时缓冲区（复用以减少GC压力）
  this._conv1Out = null;
  this._pool1Out = null;
  this._conv2Out = null;
  this._pool2Out = null;
  this._flattenOut = null;

  console.log('[PostureModel] 模型已初始化 (1D-CNN, 参数量≈6500)');
}

/**
 * 执行模型推理
 *
 * @param {Float32Array} inputData - 预处理后的传感器数据 [50×6]
 * @returns {Object} { posture: number, confidence: number, probabilities: Float32Array }
 */
PostureModel.prototype.predict = function (inputData) {
  var startTime = Date.now();

  if (!this._loaded) {
    console.error('[PostureModel] 模型未加载');
    return { posture: -1, confidence: 0, probabilities: new Float32Array(5) };
  }

  // 检查输入维度
  var expectedLen = constants.MODEL_WINDOW_SIZE * constants.MODEL_INPUT_CHANNELS;
  if (inputData.length !== expectedLen) {
    console.error('[PostureModel] 输入维度错误: 期望' + expectedLen + ', 实际' + inputData.length);
    return { posture: -1, confidence: 0, probabilities: new Float32Array(5) };
  }

  // ---- Layer 1: Conv1D + ReLU + MaxPool ----
  // 输入: [50, 6] -> Conv1D -> [50, 16] -> MaxPool -> [25, 16]
  var conv1Out = this._conv1D(inputData, constants.MODEL_WINDOW_SIZE, 6,
    CONV1_WEIGHTS, CONV1_BIAS, constants.MODEL_CONFIG.conv1);
  var relu1Out = this._relu(conv1Out, 25 * 16);
  var pool1Out = this._maxPool1D(relu1Out, 25, 16, 2);

  // ---- Layer 2: Conv1D + ReLU + MaxPool ----
  // 输入: [25, 16] -> Conv1D -> [25, 32] -> MaxPool -> [12, 32]
  var conv2Out = this._conv1D(pool1Out, 25, 16,
    CONV2_WEIGHTS, CONV2_BIAS, constants.MODEL_CONFIG.conv2);
  var relu2Out = this._relu(conv2Out, 12 * 32);
  var pool2Out = this._maxPool1D(relu2Out, 12, 32, 2);

  // ---- Layer 3: Flatten + FC + Softmax ----
  // 输入: [12, 32] = 384 -> FC -> [5] -> Softmax
  var logits = this._fullyConnected(pool2Out, 12 * 32, FC_WEIGHTS, FC_BIAS);
  var probabilities = this._softmax(logits, 5);

  // 找到最大概率的类别
  var maxIdx = 0;
  var maxVal = probabilities[0];
  for (var i = 1; i < 5; i++) {
    if (probabilities[i] > maxVal) {
      maxVal = probabilities[i];
      maxIdx = i;
    }
  }

  // 结果平滑
  this._resultBuffer.push(maxIdx);
  if (this._resultBuffer.length > this._resultBufferSize) {
    this._resultBuffer.shift();
  }
  var smoothedPosture = this._majorityVote(this._resultBuffer);
  this._currentPosture = smoothedPosture;
  this._currentConfidence = maxVal;

  // 统计推理时间
  var elapsed = Date.now() - startTime;
  this._inferenceCount++;
  this._totalInferenceTime += elapsed;

  return {
    posture: smoothedPosture,
    confidence: maxVal,
    probabilities: probabilities,
    inferenceTimeMs: elapsed
  };
};

// ============================================================
// 神经网络层实现
// ============================================================

/**
 * 1D卷积层
 *
 * @param {Float32Array} input - 输入数据 [inLength × inChannels]
 * @param {number} inLength - 输入时间步长
 * @param {number} inChannels - 输入通道数
 * @param {Float32Array} weights - 卷积核权重 [outChannels × inChannels × kernelSize]
 * @param {Float32Array} bias - 偏置 [outChannels]
 * @param {Object} config - 卷积配置 { outChannels, kernelSize, stride, padding }
 * @returns {Float32Array} 输出 [outLength × outChannels]
 */
PostureModel.prototype._conv1D = function (input, inLength, inChannels, weights, bias, config) {
  var outChannels = config.outChannels;
  var kSize = config.kernelSize;
  var stride = config.stride;
  var padding = config.padding;

  // 计算输出长度
  var outLength = Math.floor((inLength + 2 * padding - kSize) / stride) + 1;
  var output = new Float32Array(outLength * outChannels);

  for (var oc = 0; oc < outChannels; oc++) {
    for (var t = 0; t < outLength; t++) {
      var sum = bias[oc];

      for (var ic = 0; ic < inChannels; ic++) {
        for (var k = 0; k < kSize; k++) {
          var inputIdx = (t * stride + k - padding) * inChannels + ic;
          var weightIdx = (oc * inChannels + ic) * kSize + k;

          // 边界检查（padding区域补零）
          if (inputIdx >= 0 && inputIdx < input.length) {
            sum += input[inputIdx] * weights[weightIdx];
          }
        }
      }

      output[t * outChannels + oc] = sum;
    }
  }

  return output;
};

/**
 * ReLU激活函数
 *
 * @param {Float32Array} input - 输入
 * @param {number} length - 数据长度
 * @returns {Float32Array} ReLU输出
 */
PostureModel.prototype._relu = function (input, length) {
  var output = new Float32Array(length);
  for (var i = 0; i < length; i++) {
    output[i] = input[i] > 0 ? input[i] : 0;
  }
  return output;
};

/**
 * 1D最大池化层
 *
 * @param {Float32Array} input - 输入 [length × channels]
 * @param {number} length - 时间步长
 * @param {number} channels - 通道数
 * @param {number} poolSize - 池化窗口大小
 * @returns {Float32Array} 池化输出
 */
PostureModel.prototype._maxPool1D = function (input, length, channels, poolSize) {
  var outLength = Math.floor(length / poolSize);
  var output = new Float32Array(outLength * channels);

  for (var c = 0; c < channels; c++) {
    for (var t = 0; t < outLength; t++) {
      var maxVal = -Infinity;
      for (var p = 0; p < poolSize; p++) {
        var idx = (t * poolSize + p) * channels + c;
        if (idx < input.length && input[idx] > maxVal) {
          maxVal = input[idx];
        }
      }
      output[t * channels + c] = maxVal === -Infinity ? 0 : maxVal;
    }
  }

  return output;
};

/**
 * 全连接层
 *
 * @param {Float32Array} input - 展平后的特征向量 [inFeatures]
 * @param {number} inFeatures - 输入特征数
 * @param {Float32Array} weights - 权重 [outFeatures × inFeatures]
 * @param {Float32Array} bias - 偏置 [outFeatures]
 * @returns {Float32Array} 输出 logits [outFeatures=5]
 */
PostureModel.prototype._fullyConnected = function (input, inFeatures, weights, bias) {
  var outFeatures = constants.MODEL_OUTPUT_CLASSES;
  var output = new Float32Array(outFeatures);

  for (var o = 0; o < outFeatures; o++) {
    var sum = bias[o];
    for (var i = 0; i < inFeatures; i++) {
      sum += input[i] * weights[o * inFeatures + i];
    }
    output[o] = sum;
  }

  return output;
};

/**
 * Softmax函数
 * 将logits转换为概率分布
 *
 * @param {Float32Array} logits - 原始输出 [N]
 * @param {number} length - 类别数
 * @returns {Float32Array} 概率分布 [N], 和为1
 */
PostureModel.prototype._softmax = function (logits, length) {
  var output = new Float32Array(length);

  // 找最大值（数值稳定性）
  var maxVal = logits[0];
  for (var i = 1; i < length; i++) {
    if (logits[i] > maxVal) maxVal = logits[i];
  }

  // 计算exp和sum
  var sum = 0;
  for (var i = 0; i < length; i++) {
    output[i] = Math.exp(logits[i] - maxVal);
    sum += output[i];
  }

  // 归一化
  for (var i = 0; i < length; i++) {
    output[i] /= sum;
  }

  return output;
};

/**
 * 多数投票（结果平滑）
 *
 * @param {Array} results - 最近N次推理结果
 * @returns {number} 投票最多的姿态ID
 */
PostureModel.prototype._majorityVote = function (results) {
  if (results.length === 0) return -1;

  var counts = {};
  for (var i = 0; i < results.length; i++) {
    var r = results[i];
    counts[r] = (counts[r] || 0) + 1;
  }

  var maxCount = 0;
  var maxPosture = results[0];
  for (var key in counts) {
    if (counts[key] > maxCount) {
      maxCount = counts[key];
      maxPosture = parseInt(key);
    }
  }

  return maxPosture;
};

/**
 * 获取模型状态信息
 *
 * @returns {Object} 模型状态
 */
PostureModel.prototype.getStatus = function () {
  return {
    loaded: this._loaded,
    inferenceCount: this._inferenceCount,
    avgInferenceTime: this._inferenceCount > 0
      ? (this._totalInferenceTime / this._inferenceCount).toFixed(1) + 'ms'
      : 'N/A',
    currentPosture: this._currentPosture,
    currentConfidence: (this._currentConfidence * 100).toFixed(1) + '%',
    parameterCount: this._countParameters()
  };
};

/**
 * 计算模型参数量
 *
 * @returns {number} 总参数量
 */
PostureModel.prototype._countParameters = function () {
  var conv1Params = 16 * 6 * 5 + 16;   // weights + bias
  var conv2Params = 32 * 16 * 3 + 32;
  var fcParams = 5 * 384 + 5;
  return conv1Params + conv2Params + fcParams;
};

module.exports = PostureModel;

